package bo.colbert.cobros;

import android.app.*;
import android.content.*;
import android.os.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.*;
import java.lang.Process;

public final class BillingService extends Service {
 public static volatile boolean active;public static volatile String status="Servidor apagado";
 private volatile boolean stopped;private Process tunnel;private BillingHttp http;private PowerManager.WakeLock wake;
 private final ScheduledExecutorService worker=Executors.newSingleThreadScheduledExecutor();
 @Override public void onCreate(){super.onCreate();NotificationManager n=getSystemService(NotificationManager.class);n.createNotificationChannel(new NotificationChannel("billing-server","Servidor de cobros",NotificationManager.IMPORTANCE_LOW));PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,BillingActivity.class),PendingIntent.FLAG_IMMUTABLE);startForeground(57,new Notification.Builder(this,"billing-server").setSmallIcon(R.drawable.ic_billing).setContentTitle("Colbert · Servidor de cobros activo").setContentText("Recibe comprobantes y valida los permisos de tus clientes.").setContentIntent(open).setOngoing(true).build());wake=getSystemService(PowerManager.class).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"COLBERT:billing-server");wake.setReferenceCounted(false);
  worker.scheduleWithFixedDelay(()->{synchronized(this){if(stopped)return;try{BillingRuntime r=BillingRuntime.get(this);if(r.config==null||r.privateKey==null)throw new IOException("Abre la app y prepara el servidor.");if(http==null){BillingHttp candidate=new BillingHttp(r);candidate.start(8790);http=candidate;}wake.acquire(10*60*1000L);if(tunnel==null||!tunnel.isAlive())startTunnel(r);active=true;}catch(Exception e){status="No se pudo conectar. Abre la app y revisa internet.";}}},0,5,TimeUnit.SECONDS);
 }
 private void startTunnel(BillingRuntime r)throws Exception{File binary=new File(getApplicationInfo().nativeLibraryDir,"libcloudflared.so"),dir=new File(getFilesDir(),"billing-tunnel");if(!binary.canExecute())throw new IOException("Conector no incluido.");if(!dir.exists()&&!dir.mkdirs())throw new IOException("Directorio");File credentials=new File(dir,"credentials.json"),yaml=new File(dir,"config.yml");try(FileOutputStream out=new FileOutputStream(credentials)){out.write(r.config.getJSONObject("tunnel").toString().getBytes(StandardCharsets.UTF_8));}String tunnelId=r.config.getJSONObject("tunnel").getString("TunnelID");String content="tunnel: "+tunnelId+"\ncredentials-file: "+credentials.getAbsolutePath()+"\nprotocol: http2\ningress:\n  - hostname: "+new java.net.URL(r.config.getString("url")).getHost()+"\n    service: http://127.0.0.1:8790\n  - service: http_status:404\n";try(FileOutputStream out=new FileOutputStream(yaml)){out.write(content.getBytes(StandardCharsets.UTF_8));}ProcessBuilder b=new ProcessBuilder(binary.getAbsolutePath(),"tunnel","--config",yaml.getAbsolutePath(),"--no-autoupdate","run",tunnelId);b.directory(dir);b.redirectErrorStream(true);tunnel=b.start();status="Conectando el túnel de permisos…";Process p=tunnel;Thread logs=new Thread(()->{try(BufferedReader in=new BufferedReader(new InputStreamReader(p.getInputStream(),StandardCharsets.UTF_8))){String s;while((s=in.readLine())!=null){if(s.contains("Registered tunnel connection"))status="Túnel conectado · servidor de permisos activo";else if(s.contains("Unregistered tunnel connection")||s.contains("Failed to serve tunnel connection"))status="Reconectando túnel · revisa internet";}}catch(IOException ignored){}},"billing-tunnel");logs.setDaemon(true);logs.start();}
 static void notifyReceipt(Context context){if(Build.VERSION.SDK_INT>=33&&context.checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)return;try{NotificationManager manager=context.getSystemService(NotificationManager.class);manager.createNotificationChannel(new NotificationChannel("billing-payments","Solicitudes de pago",NotificationManager.IMPORTANCE_DEFAULT));PendingIntent open=PendingIntent.getActivity(context,1,new Intent(context,BillingActivity.class),PendingIntent.FLAG_IMMUTABLE);manager.notify(58,new Notification.Builder(context,"billing-payments").setSmallIcon(R.drawable.ic_billing).setContentTitle("Nuevo comprobante recibido").setContentText("Abre Colbert Cobros para verificar el pago y revisar la solicitud.").setContentIntent(open).setAutoCancel(true).setVisibility(Notification.VISIBILITY_PRIVATE).build());}catch(SecurityException ignored){/* Receipt remains stored even without notification permission. */}}
 @Override public int onStartCommand(Intent i,int flags,int id){return START_NOT_STICKY;}
 @Override public IBinder onBind(Intent i){return null;}
 @Override public synchronized void onDestroy(){stopped=true;active=false;status="Servidor apagado";worker.shutdownNow();if(http!=null)http.close();if(tunnel!=null)tunnel.destroyForcibly();if(wake!=null&&wake.isHeld())wake.release();super.onDestroy();}
}
